ee:message.ee:set-payload:
%dw 2.0
output application/json
var cabecera = vars.inputBody.RequestResSolPortDon.CabeceraMensaje
---
{
  "MensajeABD": {
    "CabeceraMensaje": {
      "IdentificadorProceso": cabecera.IdentificadorProceso,
      "IdentificadorMensaje": vars.idMessage.consecutivo,
      "FechaCreacionMsg": cabecera.FechaCreacionMsg,
      "TipoMsg": cabecera.TipoMsg,
      "Emisor": cabecera.Emisor,
      "Observaciones": cabecera.Observaciones
    },
    "CuerpoMensaje": vars.inputBody.RequestResSolPortDon.CuerpoMensaje
    }
}

%dw 2.0
output application/json
---
{
  "body": payload,
  "attachments": if (!isEmpty(vars.finalDocuments)) {
  	parts: vars.finalDocuments reduce ((item, accumulator={}) -> 
  		accumulator ++ {"$(item.fileName)": {content: item.fileContent}}
  	)
  } else null
}
